const MINIFIER_REGEX_PRECEDING_KEYWORD = /(^|[^\w$])(return|typeof|instanceof|in|of|new|delete|void|throw|do|else|case|yield|await)$/;function minifierIsRegexContext(out){const trimmed = out.replace(/\s+$/, "");if (trimmed === "") return true;const lastChar = trimmed[trimmed.length - 1];if (/[\w$)\]]/.test(lastChar)){return MINIFIER_REGEX_PRECEDING_KEYWORD.test(trimmed);}if (lastChar === '"' || lastChar === "'" || lastChar === "`") return false;return true;} function minifierFindTemplateLiteralEnd(text, start){const n = text.length;let i = start + 1;while (i < n){if (text[i] === "\\" && i + 1 < n){i += 2;continue;}if (text[i] === "`") return i + 1;if (text[i] === "$" && text[i + 1] === "{"){i = minifierSkipInterpolationExpression(text, i + 2);continue;}i++;}return i;} function minifierSkipInterpolationExpression(text, start){const n = text.length;let i = start;let depth = 0;while (i < n){const ch = text[i];if (ch === '"' || ch === "'"){const quote = ch;i++;while (i < n && text[i] !== quote){if (text[i] === "\\" && i + 1 < n) i += 2;else i++;}i++;continue;}if (ch === "`"){i = minifierFindTemplateLiteralEnd(text, i);continue;}if (ch === "{"){depth++;i++;continue;}if (ch === "}"){if (depth === 0) return i + 1;depth--;i++;continue;}i++;}return i;}function minifyStringSafe(text,{allowLineComments, tightenChars, stripSemicolonBeforeBrace}){let out = "";let i = 0;const n = text.length;while (i < n){const ch = text[i]; if (ch === "`"){const end = minifierFindTemplateLiteralEnd(text, i);out += text.slice(i, end);i = end;continue;} if (ch === '"' || ch === "'"){const quote = ch;out += ch;i++;while (i < n && text[i] !== quote){if (text[i] === "\\" && i + 1 < n){out += text[i] + text[i + 1];i += 2;}else{out += text[i];i++;}}if (i < n){out += text[i];i++;}continue;} if (ch === "/" && text[i + 1] === "*"){i += 2;while (i < n && !(text[i] === "*" && text[i + 1] === "/")) i++;i += 2;continue;} if (allowLineComments && ch === "/" && text[i + 1] !== "/" && minifierIsRegexContext(out)){let j = i + 1;let inClass = false;let terminated = false;while (j < n){if (text[j] === "\\" && j + 1 < n){j += 2;continue;}if (text[j] === "["){inClass = true;j++;continue;}if (text[j] === "]"){inClass = false;j++;continue;}if (text[j] === "\n") break; if (text[j] === "/" && !inClass){j++;terminated = true;break;}j++;}if (terminated){while (j < n && /[a-z]/i.test(text[j])) j++; out += text.slice(i, j);i = j;continue;}} if (allowLineComments && ch === "/" && text[i + 1] === "/"){while (i < n && text[i] !== "\n") i++;continue;} if (tightenChars.includes(ch)){out = out.replace(/\s+$/, "");if (stripSemicolonBeforeBrace && ch === "}" && out.endsWith(";")) out = out.slice(0, -1);out += ch;i++;while (i < n && /\s/.test(text[i])) i++;continue;} if (/\s/.test(ch)){while (i < n && /\s/.test(text[i])) i++;if (out && !/\s$/.test(out)) out += " ";continue;}out += ch;i++;}return out.trim();}function minifyCss(text){return minifyStringSafe(text,{allowLineComments: false, tightenChars: "{}:;,", stripSemicolonBeforeBrace: true});}function minifyJs(text){ return minifyStringSafe(text,{allowLineComments: true, tightenChars: "{};", stripSemicolonBeforeBrace: false});} function beautifyByBraceDepth(text){let depth = 0;let out = "";let i = 0;const n = text.length;while (i < n){const ch = text[i];if (ch === '"' || ch === "'" || ch === "`"){const quote = ch;out += ch;i++;while (i < n && text[i] !== quote){if (text[i] === "\\" && i + 1 < n){out += text[i] + text[i + 1];i += 2;}else{out += text[i];i++;}}if (i < n){out += text[i];i++;}continue;}if (ch === "{"){depth++;out += " {\n" + "  ".repeat(depth);i++;continue;}if (ch === "}"){depth = Math.max(0, depth - 1);out = out.replace(/\s+$/, "");out += "\n" + "  ".repeat(depth) + "}\n" + "  ".repeat(depth);i++;continue;}if (ch === ";"){out += ";\n" + "  ".repeat(depth);i++;continue;}out += ch;i++;}return out.split("\n").map((l) => l.trimEnd()).filter((l, idx, arr) => l !== "" || idx === arr.length - 1).join("\n");}function executeMinify(){const raw = document.getElementById("minify-input").value;const lang = document.querySelector('input[name="minify-lang"]:checked').value;const mode = document.querySelector('input[name="minify-mode"]:checked').value;const out = document.getElementById("minify-result");const stats = document.getElementById("minify-stats");if (!raw.trim()){GAMA.say("idle");out.textContent = "";stats.textContent = "";return;}const minified = lang === "css" ? minifyCss(raw) : minifyJs(raw);const result = mode === "minify" ? minified : beautifyByBraceDepth(minified);out.textContent = result;const before = new TextEncoder().encode(raw).length;const after = new TextEncoder().encode(result).length;const pct = before ? Math.round((1 - after / before) * 100) : 0;stats.textContent = mode === "minify" ? `${before}B → ${after}B (${pct >= 0 ? pct + "% smaller" : Math.abs(pct) + "% larger"})` : `${after}B beautified`;GAMA.say("success");}const executeMinifyDebounced = GAMA.debounce(executeMinify, 300);